public Rate getRate(String pair) {
    Rate r = cache.get(pair);
    if (r != null) return r;                 // hit
    r = repository.findByPair(pair);         // miss: go to the database
    cache.put(pair, r, Duration.ofMinutes(5)); // fill with a TTL
    return r;
}

public void updateRate(String pair, Rate r) {
    repository.save(r);                      // 1) write the source of truth
    cache.evict(pair);                       // 2) delete, don't update, the cached copy
}
